(4750, 7, '2023-08-07 16:30:10', '2023-08-07 08:30:10', ' /* 相片標題頁面 */\n .container-all{\n        padding: 0 4%;\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        grid-gap: 20px;\n    }\n\n\n    .container-all .titlebox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n        text-decoration:none;\n    }\n\n    .container-all .titlebox img{\n        width: 100%;\n        border-top-left-radius: 15px;\n        border-top-right-radius: 15px;\n        height: 360px;\n        object-fit: cover;\n    }\n\n    .container-all .titlebox h2{\n        /* text-align: center; */\n        font-size: 22px;\n        /* line-height: 30px; */\n        color: #fff;\n        background-color: #286090;\n        padding: 10px;\n        border-bottom-left-radius: 15px;\n        border-bottom-right-radius: 15px;\n        margin-top: -5px;\n        \n    }	\n\n\n\n/* 相片頁面CSS */\n.container01{\n        width: 1400px;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 20px;\n    }\n\n    .container01 .imgbox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n			  overflow:hidden;\n    }\n\n    .container01 .imgbox img{\n        max-width: 100%;\n        border-radius: 15px;\n			  transition: 0.5s;\n    }\n.container01 .imgbox img:hover{\n        transform: scale(1.2);\n    }\n\n    @media (max-width: 1200px){\n        .container01{\n            width: calc(100% - 40px);\n            columns: 3;\n        }\n    }\n\n    @media (max-width: 768px){\n        .container01{\n            columns: 2;\n        }\n    }\n\n    @media (max-width: 480px){\n        .container01{\n            columns: 1;\n        }\n    }', '2020', '', 'inherit', 'closed', 'closed', '', '4622-revision-v1', '', '', '2023-08-07 16:30:10', '2023-08-07 08:30:10', '', 4622, 'https://astcc.asia/4622-revision-v1/', 0, 'revision', '', 0),
