(4873, 7, '2023-08-08 09:40:31', '2023-08-08 01:40:31', '.flex-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 20px;\n  max-width: 1500px;\n  margin: auto;\n	padding:0 3%;\n}\n\n.title-box {\n  flex-basis: calc(33.333% - 20px); /* 三列佈局，減去間距 */\n  position: relative; /* 用於定位標題 */\n}\n\n.title-box a {\n  display: block;\n  text-decoration: none;\n  color: inherit;\n}\n\n.title-box img {\n  max-width: 100%;\n  height: 320px;\n	object-fit: cover;\n	\n}\n\n.image-title {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  padding: 10px;\n  background-color: rgba(0, 0, 0, 0.8);\n  color: white;\n  margin: 0;\n	font-size: 20px;\n}\n\n\n\n\n/* 相片分頁 */\n.container01{\n        width: 1400px;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 20px;\n    }\n\n    .container01 .imgbox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n    }\n\n    .container01 .imgbox img{\n        max-width: 100%;\n        border-radius: 15px;\n    }\n\n    @media (max-width: 1200px){\n        .container01{\n            width: calc(100% - 40px);\n            columns: 3;\n        }\n    }\n\n    @media (max-width: 768px){\n        .container01{\n            columns: 2;\n        }\n    }\n\n    @media (max-width: 480px){\n        .container01{\n            columns: 1;\n        }\n    }\n\n', '2020', '', 'inherit', 'closed', 'closed', '', '4622-revision-v1', '', '', '2023-08-08 09:40:31', '2023-08-08 01:40:31', '', 4622, 'https://astcc.asia/4622-revision-v1/', 0, 'revision', '', 0),
