(5568, 7, '2023-10-11 10:19:08', '2023-10-11 02:19:08', '.flex-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 20px;\n  max-width: 1500px;\n  margin: auto;\n	padding:0 3%;\n}\n\n\n.title-box {\n  flex-basis: calc(33.333% - 20px); /* 三列佈局，減去間距 */\n  position: relative; /* 用於定位標題 */\n}\n\n.title-box a {\n  display: block;\n  text-decoration: none;\n  color: inherit;\n}\n\n.title-box img {\n  max-width: 100%;\n  height: 320px;\n	object-fit: cover;\n	\n}\n\n.image-title {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  padding: 10px;\n  background-color: rgba(0, 0, 0, 0.8);\n  color: white;\n  margin: 0;\n	font-size: 20px;\n}\n\n\n/* 相片分頁 */\n.container01{\n        max-width: 1400px;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 20px;\n    }\n\n.container01 .imgbox{\n        width: 100%;\n        margin-bottom: 30px;\n        break-inside: avoid;\n        overflow: hidden;\n        border-radius: 15px;\n    }\n\n    .container01 .imgbox img{\n        max-width: 100%;\n        transition: 0.5s;\n    }\n\n\n    .container01 .imgbox img:hover {\n    transform: scale(1.2);\n}\n\n    @media (max-width: 1200px){\n        .container01{\n            width: calc(100% - 40px);\n            columns: 3;\n        }\n			  .title-box img {\n            max-height: 260px;\n        }\n    }\n\n    @media (max-width: 768px){\n        .container01{\n            columns: 2;\n        }\n			  .title-box {\n            flex-basis: calc(50% - 20px); \n        }\n    }\n\n    @media (max-width: 480px){\n        .container01{\n            columns: 1;\n        }\n			  .title-box {\n            flex-basis: calc(100% - 20px); \n        }\n    }\n\n/* 相片分頁有文字敘述 */\n.container02{\n        max-width: 1400px;\n        margin: 20px auto;\n    }\n\n\n\n/* 時間軸 */\n#tl-timeline-iframe{\n	margin:auto;\n}\n\n.container03{\n/*         max-width: 1400px; */\n        margin: 20px auto;\n    }', '2020', '', 'inherit', 'closed', 'closed', '', '4622-revision-v1', '', '', '2023-10-11 10:19:08', '2023-10-11 02:19:08', '', 4622, 'https://astcc.asia/4622-revision-v1/', 0, 'revision', '', 0),
