DROP TABLE IF EXISTS `astc_schedule`;
CREATE TABLE IF NOT EXISTS `astc_schedule` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `year` varchar(50) NOT NULL,
  `month` varchar(20) NOT NULL,
  `day` varchar(10) NOT NULL,
  `weekdays` varchar(10) NOT NULL,
  `time` varchar(30) DEFAULT NULL,
  `branch` varchar(150) DEFAULT NULL,
  `place` varchar(255) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `date` varchar(15) NOT NULL,
  `status` varchar(10) DEFAULT NULL,
  `create-date` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

